-- ============================================================================
-- data.sql -- SYNTHETIC dementia screening dataset (Zimbabwe calibration)
-- Generated by generate_data.py (seed=42). Regenerate: python generate_data.py
-- ============================================================================
--
-- PROVENANCE / ETHICS DISCLAIMER
--   This dataset is 100% SYNTHETIC. It contains NO real patient records.
--   It was generated procedurally so that marginal distributions are
--   plausible for a community sample of adults aged >=60 in Zimbabwe.
--   Any analysis results obtained from it are ILLUSTRATIVE ONLY and must
--   never be quoted as findings about Zimbabwe.
--
-- CALIBRATION ANCHORS (approximate, published sources)
--   Age structure, 10-province weights, ~30% urban share .... ZIMSTAT,
--       2022 Population and Housing Census of Zimbabwe
--   Overall dementia prevalence target ~7.8% (rising with age) ... pooled
--       Sub-Saharan Africa estimates (Guerchet et al.; HAALSI/de Jager et al.,
--       Neurology 2017, rural South Africa)
--   Hypertension common among 60+, treatment coverage <50% ... WHO STEPS
--       Zimbabwe 2014; SSA elderly reviews
--   Diabetes ~5-10% adults ... STEPS 2014 / IDF SSA region
--   Adult HIV prevalence ~11-12%; assumed 3-6% among 60+ (ASSUMPTION,
--       flagged) ... UNAIDS AIDSinfo country profile: Zimbabwe
--   Smoking male-skewed (~15% men, ~1-2% women) ... STEPS 2014
--   High widowhood among elderly women; low schooling in oldest cohorts ...
--       DHS/MICS attainment patterns; colonial-era access
--   Low USD household incomes, informal economy ... World Bank/ZIMSTAT
--
-- ENGINE COMPATIBILITY
--   Portable ANSI-style SQL (INTEGER/REAL/TEXT only, explicit IDs).
--   Tested target: SQLite. Also loads on PostgreSQL and MySQL.
--   NOTE: interview_date is TEXT because three date formats coexist
--   deliberately; strict DATE columns would reject some engines' inserts.
--   No PRIMARY KEY constraint on participant_id: exact duplicates exist
--   by design (cleaning exercise).
--
-- IMPORT
--   SQLite : sqlite3 dementia.db < data.sql
--   psql   : psql -f data.sql
--   MySQL  : mysql -e "SOURCE data.sql"  (or pipe it in)
--
-- CONTENTS
--   dementia_screening : 12168 inserted rows (12000 unique participants)
--   data_dictionary    : column definitions
--   noise_manifest     : engineered defects + cleaning recommendations
--   Suggested QA queries at bottom of file.
-- ============================================================================

BEGIN TRANSACTION;

DROP TABLE IF EXISTS dementia_screening;
DROP TABLE IF EXISTS data_dictionary;
DROP TABLE IF EXISTS noise_manifest;

CREATE TABLE dementia_screening (
    participant_id                  TEXT NOT NULL,
    interview_date                  TEXT,           -- mixed formats, see noise_manifest
    province                        TEXT,           -- 10 provinces
    residence                       TEXT,           -- Urban/Rural (dirty variants)
    sex                             TEXT,           -- M/F (dirty variants)
    age_years                       INTEGER,        -- protocol requires >= 60
    marital_status                  TEXT,
    education_years                 INTEGER,        -- completed formal schooling
    employment_status               TEXT,
    monthly_household_income_usd    REAL,
    lives_alone                     INTEGER,        -- 0/1
    social_engagement               TEXT,           -- Daily/Weekly/Rarely/Never
    hiv_status                      TEXT,           -- Positive/Negative/Unknown
    hypertension_dx                 INTEGER,        -- 0/1 self-reported diagnosis
    takes_bp_medication             INTEGER,        -- 0/1 current BP medication
    diabetes_dx                     INTEGER,        -- 0/1
    prior_stroke                    INTEGER,        -- 0/1
    head_injury_history             INTEGER,        -- 0/1 significant TBI history
    family_history_dementia         INTEGER,        -- 0/1 first-degree relative
    systolic_bp_mmhg                INTEGER,        -- mean of 2 seated readings
    diastolic_bp_mmhg               INTEGER,
    bmi_kg_m2                       REAL,
    gds15_score                     INTEGER,        -- Geriatric Depression Scale 0-15
    hearing_difficulty              INTEGER,        -- 0/1 self-reported
    vision_difficulty               INTEGER,        -- 0/1 self-reported
    smoking_status                  TEXT,           -- Never/Former/Current (dirty)
    alcohol_use                     TEXT,           -- None/Moderate/Hazardous (dirty)
    physical_activity_level         TEXT,           -- Low/Moderate/High
    fruit_veg_servings_per_day      INTEGER,
    cognitive_screen_score          INTEGER,        -- 0-30 MMSE/CSI-D-style screen;
                                                    -- OUTCOME ASCERTAINMENT VARIABLE:
                                                    -- EXCLUDE from predictors (leakage)
    dementia_status                 INTEGER NOT NULL -- DEPENDENT VARIABLE 0/1,
                                                     -- clinician-consensus gold standard
);

-- ---------------------------------------------------------------------------
-- Main table inserts (12168 rows; 12000 unique participant_id values)
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- Data dictionary
-- ---------------------------------------------------------------------------
CREATE TABLE data_dictionary (
    column_name      TEXT NOT NULL,
    data_type        TEXT,
    allowed_values   TEXT,
    description      TEXT
);

-- ---------------------------------------------------------------------------
-- Noise manifest: engineered defects + recommended cleaning actions
-- ---------------------------------------------------------------------------
CREATE TABLE noise_manifest (
    noise_id                INTEGER NOT NULL,
    noise_category          TEXT,
    affected_columns        TEXT,
    approx_count            TEXT,
    example_value           TEXT,
    cleaning_recommendation TEXT
);

COMMIT;

-- ---------------------------------------------------------------------------
-- Suggested post-import QA queries (run manually)
-- ---------------------------------------------------------------------------
-- Row counts and duplicates:
--   SELECT COUNT(*) AS rows_total, COUNT(DISTINCT participant_id) AS uniq FROM dementia_screening;
-- Crude prevalence among protocol-eligible unique participants:
--   SELECT AVG(dementia_status) FROM dementia_screening WHERE age_years BETWEEN 60 AND 110;
--   (deduplicate first!)
-- Distinct dirty categories:
--   SELECT DISTINCT sex FROM dementia_screening ORDER BY sex;
--   SELECT DISTINCT interview_date LIKE '%/%' FROM dementia_screening LIMIT 5;
-- Sentinel scan:
--   SELECT COUNT(*) FROM dementia_screening WHERE gds15_score IN (-99, 88, 99);

-- End of data.sql
