INSERT INTO data_dictionary VALUES ('participant_id', 'TEXT', '''ZW-#####''', 'Pseudonymised participant identifier. NOT unique in raw table (duplicates by design).');
INSERT INTO data_dictionary VALUES ('interview_date', 'TEXT', '3 formats: ISO, DD/MM/YYYY, ''Mon D, YYYY''', 'Date of Phase-1 interview within 2024-01-08..2025-03-31 fieldwork window.');
INSERT INTO data_dictionary VALUES ('province', 'TEXT', '10 Zimbabwe provinces (+dirty variants)', 'Province of residence.');
INSERT INTO data_dictionary VALUES ('residence', 'Text', 'Urban/Rural (+dirty variants)', 'Urban or rural residence.');
INSERT INTO data_dictionary VALUES ('sex', 'TEXT', 'M/F (+dirty variants)', 'Sex of participant.');
INSERT INTO data_dictionary VALUES ('age_years', 'INTEGER', '>=60 per protocol (violations exist)', 'Age in completed years at interview.');
INSERT INTO data_dictionary VALUES ('marital_status', 'TEXT', 'Married/Widowed/Divorced-Separated/Never Married (+variants)', 'Current marital status.');
INSERT INTO data_dictionary VALUES ('education_years', 'INTEGER', '0-16 (+impossible values)', 'Completed years of formal schooling.');
INSERT INTO data_dictionary VALUES ('employment_status', 'TEXT', 'Retired/Subsistence Farming/Informal Trading/Formal Employment/Unemployed (+synonyms)', 'Main current occupation.');
INSERT INTO data_dictionary VALUES ('monthly_household_income_usd', 'REAL', '>0 (+88/99 sentinels, NULL)', 'Self-reported household income, USD per month.');
INSERT INTO data_dictionary VALUES ('lives_alone', 'INTEGER', '0/1', 'Lives alone in household.');
INSERT INTO data_dictionary VALUES ('social_engagement', 'TEXT', 'Daily/Weekly/Rarely/Never (+variants)', 'Frequency of social contact outside household.');
INSERT INTO data_dictionary VALUES ('hiv_status', 'TEXT', 'Positive/Negative/Unknown', 'Self-reported HIV status; Unknown includes never-tested/refusal.');
INSERT INTO data_dictionary VALUES ('hypertension_dx', 'INTEGER', '0/1', 'Ever told by health worker they have high blood pressure.');
INSERT INTO data_dictionary VALUES ('takes_bp_medication', 'INTEGER', '0/1 (+NULL)', 'Currently taking blood-pressure medication.');
INSERT INTO data_dictionary VALUES ('diabetes_dx', 'INTEGER', '0/1', 'Ever told they have diabetes.');
INSERT INTO data_dictionary VALUES ('prior_stroke', 'INTEGER', '0/1', 'Self/family-reported prior stroke episode.');
INSERT INTO data_dictionary VALUES ('head_injury_history', 'INTEGER', '0/1', 'History of significant head injury with loss of consciousness.');
INSERT INTO data_dictionary VALUES ('family_history_dementia', 'INTEGER', '0/1', 'Dementia in a first-degree relative.');
INSERT INTO data_dictionary VALUES ('systolic_bp_mmhg', 'INTEGER', '~80-260 (+NULL, transpositions)', 'Mean seated systolic BP, mmHg.');
INSERT INTO data_dictionary VALUES ('diastolic_bp_mmhg', 'INTEGER', '~45-140 (+NULL, transpositions)', 'Mean seated diastolic BP, mmHg.');
INSERT INTO data_dictionary VALUES ('bmi_kg_m2', 'REAL', '~13.5-45 (+impossible values)', 'Body mass index, kg/m^2.');
INSERT INTO data_dictionary VALUES ('gds15_score', 'INTEGER', '0-15 (+sentinels, impossible values)', 'Geriatric Depression Scale short-form score.');
INSERT INTO data_dictionary VALUES ('hearing_difficulty', 'INTEGER', '0/1', 'Self-reported difficulty hearing (with aid if owned).');
INSERT INTO data_dictionary VALUES ('vision_difficulty', 'INTEGER', '0/1', 'Self-reported difficulty seeing (with aid if owned).');
INSERT INTO data_dictionary VALUES ('smoking_status', 'TEXT', 'Never/Former/Current (+synonyms like ''Ex-smoker'', ambiguous ''Yes'')', 'Tobacco smoking status.');
INSERT INTO data_dictionary VALUES ('alcohol_use', 'TEXT', 'None/Moderate/Hazardous (+synonyms)', 'Alcohol use category (AUDIT-C style grouping).');
INSERT INTO data_dictionary VALUES ('physical_activity_level', 'TEXT', 'Low/Moderate/High', 'IPAQ-style composite physical activity level.');
INSERT INTO data_dictionary VALUES ('fruit_veg_servings_per_day', 'INTEGER', '0-8 (+sentinels, impossible values)', 'Usual daily servings of fruit and/or vegetables.');
INSERT INTO data_dictionary VALUES ('cognitive_screen_score', 'INTEGER', '0-30 (+NULL)', 'MMSE/CSI-D-style composite screen. USED IN OUTCOME ASCERTAINMENT - do NOT use as predictor (data leakage).');
INSERT INTO data_dictionary VALUES ('dementia_status', 'INTEGER', '0/1', 'DEPENDENT VARIABLE. Clinician-consensus dementia diagnosis (gold-standard simulation). Never NULL.');
INSERT INTO noise_manifest VALUES (1, 'Missingness MCAR', 'many numeric/categorical columns', '~2-6% per column', 'NULL', 'Profile missingness per column; impute AFTER train/test split (median/mode fitted on train only) or complete-case sensitivity analysis.');
INSERT INTO noise_manifest VALUES (2, 'Missingness MAR', 'monthly_household_income_usd', '~18% rural vs ~7% urban', 'NULL', 'Income under-reporting concentrated in rural households; consider missing-indicator flag plus imputation.');
INSERT INTO noise_manifest VALUES (3, 'Survey sentinel codes', 'income, education, GDS, fruit/veg', '~291 cells+', '-99 / 88 / 99', 'Map -99=Refusal, 88=Don''t know, 99=Not applicable -> NULL before any arithmetic; NEVER treat as valid numbers.');
INSERT INTO noise_manifest VALUES (4, 'Exact duplicates', 'whole rows', '120 rows', 'same participant_id twice', 'Detect via GROUP BY participant_id HAVING COUNT(*)>1; keep one; document conflict rule.');
INSERT INTO noise_manifest VALUES (5, 'Fuzzy duplicates', 'whole rows', '48 rows', 'same id, age +/-1', 'Near-duplicates with tiny jitter; deduplicate on participant_id keeping first occurrence.');
INSERT INTO noise_manifest VALUES (6, 'Impossible values', 'age_years', '~64 cells', '999, -5, 160', 'Range-check against protocol (>=60, plausibility cap ~105); route to rejection log, do not silently overwrite.');
INSERT INTO noise_manifest VALUES (7, 'Impossible values', 'bmi_kg_m2', '~48 cells', '78.4, 4.7', 'Physiologic bounds ~10-70; set NULL and flag.');
INSERT INTO noise_manifest VALUES (8, 'Unit/transposition errors', 'systolic_bp_mmhg, diastolic_bp_mmhg', '~56 rows', 'dia >= sys', 'Where diastolic >= systolic assume transposition; swap then validate; else reject.');
INSERT INTO noise_manifest VALUES (9, 'Impossible values', 'education_years, gds15_score, fruit_veg_servings_per_day', '~32 cells', '44 school years; GDS 27; -3 servings', 'Domain range checks (edu<=16~20, GDS 0-15, servings>=0).');
INSERT INTO noise_manifest VALUES (10, 'Category inconsistencies', 'sex, province, residence, marital, employment, smoking, alcohol, social, HIV', '~5320 cells', '''MALE '', ''widwoed'', ''Hre''', 'Build controlled vocabularies + mapping tables; trim whitespace; casefold; fuzzy-match misspellings.');
INSERT INTO noise_manifest VALUES (11, 'Whitespace padding', 'several text columns', '~440 cells', ''' Vendor ''', 'TRIM all text fields early in pipeline.');
INSERT INTO noise_manifest VALUES (12, 'Date format inconsistency', 'interview_date', '3 formats across file', '''15/03/2024'' vs ''2024-03-15'' vs ''Mar 15, 2024''', 'Parse with explicit multi-format parser; fail loudly on unparseable dates.');
INSERT INTO noise_manifest VALUES (13, 'Logical contradictions', 'hypertension_dx vs takes_bp_medication', '~80 rows', 'medication=1 but dx=0', 'Flag contradictions; decide keep-as-missing vs keep-with-flag; document choice.');
INSERT INTO noise_manifest VALUES (14, 'Inclusion violations', 'age_years', '~48 rows', 'age 48-53', 'Apply eligibility filter age>=60 after cleaning; report excluded count.');
